<template>
  <div class="chat-surface" :class="{ compact }">
    <section ref="scrollArea" class="messages" aria-label="聊天消息" @scroll="trackScroll">
      <div v-if="store.loading" class="chat-loading">正在加载会话…</div>
      <div v-else-if="!store.history.length && !store.running && !store.answer" class="welcome"><span class="welcome-mark"><i class="i-lucide-sparkles" /></span><p class="welcome-kicker">你的知识，随问随得</p><h1>有什么可以帮你？</h1><p>从知识库中寻找答案，把想法变成行动。</p><div v-if="!compact" class="suggestions"><button v-for="question in suggestions" :key="question.title" @click="store.query = question.query"><i :class="question.icon" /><strong>{{ question.title }}</strong><span>{{ question.subtitle }}</span><i class="i-lucide-arrow-up-right" /></button></div></div>
      <div class="message-list"><article v-for="message in store.history" :key="message.id" class="message" :class="message.role === 'USER' ? 'user' : 'assistant'"><span class="message-avatar"><i :class="message.role === 'USER' ? 'i-lucide-user-round' : 'i-lucide-sparkles'" /></span><div class="message-content"><small>{{ message.role === 'USER' ? '你' : 'kwiki' }}</small><div v-if="message.role === 'USER'" class="user-text">{{ message.content }}</div><template v-else><RetrievalActivity v-if="store.runActivities[message.requestId ?? '']?.length" :steps="store.runActivities[message.requestId ?? '']" :running="false" :failed="false" /><div class="markdown" v-html="renderMarkdown(message.content)" /></template></div></article>
      <article v-if="store.running || store.answer" class="message assistant"><span class="message-avatar"><i class="i-lucide-sparkles" /></span><div class="message-content"><small>kwiki</small><RetrievalActivity v-if="store.state.activitySteps.length" :steps="store.state.activitySteps" :running="store.running && !store.state.terminated" :failed="!!store.state.error" /><div v-if="store.running && !store.answer" class="generating"><span class="pulse" />{{ progressLabel }}</div><div v-if="store.answer" class="markdown" v-html="renderMarkdown(store.answer)" /></div></article>
      <div v-if="store.state.citations.length" class="citations"><strong>参考来源</strong><button v-for="(citation, i) in store.state.citations" :key="citation.childChunkKey" @click="citationOpen = citation"><span>{{ i + 1 }}</span>{{ citation.headingPath || '文档片段' }}<i class="i-lucide-arrow-up-right" /></button></div>
      <div v-if="store.error || store.historyError" class="ui-error" role="alert">{{ store.historyError || store.error }}<button class="ui-button" @click="retry">{{ store.historyError ? '重新加载' : '重新提问' }}</button></div></div>
    </section>
    <form class="composer-area" @submit.prevent="store.send"><div class="composer-box"><textarea v-model="store.query" aria-label="输入问题" placeholder="向知识库提问…" rows="2" :disabled="store.loading" @keydown="onKeydown" /><div class="composer-toolbar"><button type="button" class="scope-trigger" @click="scopeOpen = true"><i class="i-lucide-library" /> {{ scopeLabel }}<i class="i-lucide-chevron-down" /></button><button v-if="store.running" type="button" class="send-button" aria-label="停止生成" @click="store.cancel"><i class="i-lucide-square" /></button><button v-else type="submit" class="send-button" aria-label="发送问题" :disabled="!store.query.trim() || store.loading || !!store.historyError"><i class="i-lucide-arrow-up" /></button></div></div><p class="composer-note">回答基于你有权访问的内容，请结合来源核实。<span v-if="!compact"> Enter 发送 · Shift + Enter 换行</span></p></form>
    <KnowledgeScopeDialog v-if="scopeOpen" @close="scopeOpen = false" />
    <div v-if="citationOpen" class="citation-overlay" @click.self="citationOpen = null"><section role="dialog" aria-label="引用来源" class="citation-dialog"><header><h3>{{ citationOpen.headingPath || '引用来源' }}</h3><button class="ui-icon" aria-label="关闭引用来源" @click="citationOpen = null"><i class="i-lucide-x" /></button></header><p>{{ citationOpen.excerpt }}</p></section></div>
  </div>
</template>
<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { useConversationStore } from './conversationStore'; import KnowledgeScopeDialog from './KnowledgeScopeDialog.vue'; import { renderMarkdown } from '../wiki/components/render'; import RetrievalActivity from '../wiki/components/RetrievalActivity.vue'; import type { CitationEntry } from '../wiki/sse';
defineProps<{ compact?: boolean }>(); const store = useConversationStore(); const scrollArea = ref<HTMLElement>(); const stick = ref(true); const citationOpen = ref<CitationEntry | null>(null); const scopeOpen = ref(false);
const scopeLabel = computed(() => { const count = store.selectedKnowledgeBaseIds.length + store.selectedPageIds.length; return count ? `已选择 ${count} 项` : '可访问的知识库'; });
const suggestions = [{ title: '快速了解', subtitle: '概括文档中的关键内容', icon: 'i-lucide-book-open', query: '请概括知识库文档中的关键内容，并列出参考来源。' }, { title: '找到答案', subtitle: '查找与你的问题相关的信息', icon: 'i-lucide-search', query: '我想了解知识库中关于' }, { title: '梳理步骤', subtitle: '将说明整理成行动清单', icon: 'i-lucide-list-checks', query: '请根据知识库内容，整理一份可执行的操作步骤。' }];
const progressLabel = computed(() => {
  const last = store.state.activitySteps.at(-1);
  return last?.summary || '正在寻找相关内容…';
});
function trackScroll() { const el = scrollArea.value; if (el) stick.value = el.scrollHeight - el.scrollTop - el.clientHeight < 100; }
watch(() => [store.answer, store.history.length, store.running], async () => { await nextTick(); if (stick.value && scrollArea.value) scrollArea.value.scrollTop = scrollArea.value.scrollHeight; });
watch(() => store.sessionId, () => { stick.value = true; });
function onKeydown(e: KeyboardEvent) { if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); store.send(); } }
function retry() { if (store.historyError) void store.select(store.sessionId); else { store.query = store.lastQuery; store.state.error = null; } }
</script>
