e h1{font-size:22px}.compact .welcome-mark{padding:12px;font-size:22px}.compact .welcome-kicker{margin-top:16px}.compact .composer-area{padding:12px 16px}.compact .composer-note{font-size:9px}.compact .message{gap:8px}.compact .message-content{font-size:13px}.citation-overlay{position:absolute;inset:0;background:#eff4efdd;z-index:10;display:grid;place-items:center;padding:20px}.citation-dialog{padding:24px;background:white;border:1px solid #e1e9e3;border-radius:12px;max-height:85%;overflow:auto;width:min(600px,100%)}.citation-dialog header{display:flex;align-items:center;justify-content:space-between;gap:10px}.citation-dialog h3{font-size:16px}.citation-dialog p{white-space:pre-wrap;line-height:1.8;color:#667d6e}.chat-loading{text-align:center;color:#91a095;margin-top:40px}@media(max-width:1000px){.messages{padding:24px}.suggestions{gap:8px}.suggestions button{padding:16px 12px}.suggestions span{line-height:1.6}.composer-area{padding:12px 24px 18px}}@media(max-width:600px){.messages{padding:18px}.welcome h1{font-size:27px}.suggestions{grid-template-columns:1fr}.suggestions button{display:grid;grid-template-columns:22px 1fr;gap:6px 10px}.suggestions span{grid-column:2}.composer-area{padding:10px 14px}.composer-note span{display:none}}
</style>
<style scoped>
.markdown :deep(p){margin:8px 0 14px}.markdown :deep(h1),.markdown :deep(h2),.markdown :deep(h3){line-height:1.5;font-size:18px;margin:24px 0 12px}.markdown :deep(h3){font-size:16px}.markdown :deep(ul),.markdown :deep(ol){padding-left:22px}.markdown :deep(li){margin:7px 0}.markdown :deep(blockquote){border-left:3px solid #c5decd;margin:16px 0;padding:2px 14px;color:#7c9283}.markdown :deep(.table-scroll){overflow:auto}.markdown :deep(table){width:100%;border-collapse:collapse;margin:16px 0;font-size:13px}.markdown :deep(th),.markdown :deep(td){border:1px solid #e1eae3;padding:8px 12px;text-align:left}.markdown :deep(th){background:#f1f6f2;font-weight:550}.markdown :deep(a){color:#43885a;text-underline-offset:3px}
